"use client";
// Quick CSS confetti burst. Pieces are generated by the caller (in an event handler), so render stays pure.

export interface ConfettiPiece {
  dx: number;
  dy: number;
  rot: number;
  color: string;
  delay: number;
}

const COLORS = ["#ff8a3d", "#22e584", "#a78bfa", "#3987e5", "#facc15"];

export function makeConfetti(n = 36): ConfettiPiece[] {
  return Array.from({ length: n }, (_, i) => {
    const angle = (Math.PI * 2 * i) / n + Math.random() * 0.4;
    const dist = 90 + Math.random() * 120;
    return {
      dx: Math.cos(angle) * dist,
      dy: Math.sin(angle) * dist - 40,
      rot: Math.random() * 720 - 360,
      color: COLORS[i % COLORS.length],
      delay: Math.random() * 80,
    };
  });
}

export default function Confetti({ pieces }: { pieces: ConfettiPiece[] }) {
  return (
    <div className="pointer-events-none absolute left-1/2 top-1/2" aria-hidden>
      {pieces.map((p, i) => (
        <span
          key={i}
          className="confetti-piece"
          style={
            {
              background: p.color,
              animationDelay: `${p.delay}ms`,
              "--dx": `${p.dx}px`,
              "--dy": `${p.dy}px`,
              "--rot": `${p.rot}deg`,
            } as React.CSSProperties
          }
        />
      ))}
    </div>
  );
}
